/* ==UserStyle==
@name Have I Been Pwned Catppuccin
@namespace github.com/catppuccin/userstyles/styles/have-i-been-pwned
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/have-i-been-pwned
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/have-i-been-pwned/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Ahave-i-been-pwned
@description Soothing pastel theme for Have I Been Pwned
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("haveibeenpwned.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      background-color: @base;
      color: @text;
    }

    hr {
      border-color: @surface0;
    }

    a {
      &,
      &:hover,
      &:focus {
        color: @text;
        border-bottom-color: @surface2;
      }

      &:hover {
        background-color: fade(@accent, 30%);
      }
    }

    img.pwnLogo.large.modalLogo {
      filter: @text-filter;
    }

    .bodyGradient {
      color: @text;
    }

    .modal-header {
      background: @crust;

      .close {
        color: @text;
      }
    }

    .fa-loader,
    .loaderText {
      color: @text;
    }

    #postNotificationCallsToAction {
      .btn {
        background-color: @crust;
        color: @text;
      }

      a.socialLink {
        &,
        &:link,
        &:visited {
          color: @text;
        }
      }
    }

    .modal-content {
      background-color: @base;
      border-color: @surface0;
    }

    .main {
      background-color: @mantle;
      color: @text;
    }

    .main-logo .logo {
      border-color: @accent;
      background-color: fade(@accent, 30%);
    }

    .pwnedCompanyList {
      a,
      a:hover {
        color: @text;
        border-bottom-color: @surface2;
      }

      td {
        color: @subtext0;
      }
    }

    footer {
      a,
      p {
        color: @subtext0;
      }
    }

    .unverified {
      &,
      a {
        color: darken(@red, 50%) !important;
        border-bottom-color: darken(@red, 50%) !important;
      }
    }

    .navbar-inverse {
      border-color: @surface0;
      background-color: @crust;

      .navbar-toggle {
        border-color: @surface0;

        &:hover,
        &:focus {
          background-color: @surface0;
        }

        .icon-bar {
          background-color: @text;
        }
      }

      .navbar-brand {
        color: @text;
        border-color: @text !important;
      }

      li.active > a {
        &,
        &:hover,
        &:focus {
          color: @text;
          background-color: @crust;
        }
      }

      li > a {
        color: @subtext0;

        &:hover,
        &:focus {
          color: @text;
        }
      }
    }

    img.pwnLogo {
      &[src$="/List.png"],
      &[src$="/Email.png"] {
        filter: @text-filter;
      }
    }

    .form-control {
      background-color: @crust;
      color: @text;
      border-color: @surface0 !important;

      &:focus {
        box-shadow: 0 0 8px fade(@accent, 30%);
      }
    }

    .btn-primary {
      color: @text;
      background-color: @crust;
      border-color: @surface0 !important;

      &:hover {
        background-color: fade(@accent, 30%);
      }
    }

    .btn-success {
      background-color: @green;
      color: @base;
      border-color: @surface0;
    }

    .progress-bar {
      background-color: @accent;
    }

    .form-group .termsOfUse {
      background-color: @base;
    }

    .termsOfUse {
      background-color: @mantle;

      &,
      a {
        color: @subtext0;
        border-bottom-color: @surface2;
      }
    }

    .secondaryHeader {
      background-color: @mantle;
    }

    .sensitive {
      color: @yellow;
    }

    .sensitive-fade {
      color: @subtext0;
    }

    .panel-primary {
      border-color: @surface0;

      > .panel-heading,
      > .panel-footer {
        color: @text;
        border-color: @surface0;
        background-color: @mantle;
      }
    }

    #noPwnage {
      background: @green;

      a.socialLink {
        color: @base !important;
      }
    }

    #invalidAccount {
      background: @yellow;
    }

    #pwnedWebsitesContainer {
      hr {
        border-color: @surface0;
      }

      > .pwnedRow {
        background: @red;

        .pwnedWebsite {
          color: @base;

          a {
            color: @base;
            border-bottom-color: @base;

            &:hover {
              background-color: transparent !important;
            }
          }
        }
      }

      a.socialLink {
        color: @base !important;
      }
    }

    .pwnResultBanner {
      color: @base;

      a {
        color: @base;
        border-bottom-color: @base !important;

        &:hover {
          background-color: transparent !important;
        }
      }
    }

    #Cloudflare img {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1239.3 310.1"><path d="M1158.5 187.7c-3.4 0-6.1-2.7-6.1-6.1 0-3.3 2.7-6.1 6.1-6.1 3.3 0 6.1 2.7 6.1 6.1s-2.8 6.1-6.1 6.1m0-11c-2.7 0-4.9 2.2-4.9 4.9s2.2 4.9 4.9 4.9 4.9-2.2 4.9-4.9-2.2-4.9-4.9-4.9m3.1 8.1h-1.4l-1.2-2.3h-1.6v2.3h-1.3v-6.7h3.2c1.4 0 2.3.9 2.3 2.2 0 1-.6 1.7-1.4 2zm-2.4-3.5c.5 0 1-.3 1-1 0-.8-.4-1-1-1h-2v2zM523 174.9h15.6v42.5h27.1V231H523zm58.8 28.2v-.1c0-16.1 13-29.2 30.3-29.2s30.1 12.9 30.1 29v.2c0 16.1-13 29.2-30.3 29.2-17.2-.1-30.1-13-30.1-29.1m44.6 0v-.1c0-8.1-5.8-15.1-14.4-15.1-8.5 0-14.2 6.9-14.2 15v.2c0 8.1 5.8 15.1 14.3 15.1 8.6-.1 14.3-7 14.3-15.1m34.9 3.3v-31.5h15.8v31.2c0 8.1 4.1 11.9 10.3 11.9s10.3-3.7 10.3-11.5v-31.6h15.8V206c0 18.1-10.3 26-26.3 26-15.9.1-25.9-8-25.9-25.6m76-31.5H759c20 0 31.7 11.5 31.7 27.7v.2c0 16.2-11.8 28.2-32 28.2h-21.3zm21.9 42.3c9.3 0 15.5-5.1 15.5-14.2v-.2c0-9-6.2-14.2-15.5-14.2h-6.3v28.5zm54-42.3h44.9v13.7h-29.4v9.5h26.6V211h-26.6v20h-15.5zm66.5 0h15.5v42.5h27.2V231h-42.7zm83.3-.4h15l23.9 56.5h-16.7l-4.1-10h-21.6l-4 10h-16.3zm13.7 34.4-6.2-15.9-6.3 15.9zm45.2-34h26.5c8.6 0 14.5 2.2 18.3 6.1 3.3 3.2 5 7.5 5 13.1v.2c0 8.6-4.6 14.3-11.5 17.2l13.4 19.6h-18l-11.3-17h-6.8v17H1022zm25.8 27c5.3 0 8.3-2.6 8.3-6.6v-.3c0-4.4-3.2-6.6-8.4-6.6h-10.2v13.5zm46.4-27h45.1v13.3h-29.7v8.4h26.9v12.3h-26.9v8.9h30.1V231h-45.5zM489 209.7c-2.2 4.9-6.8 8.4-12.8 8.4-8.5 0-14.3-7.1-14.3-15.1v-.2c0-8.1 5.7-15 14.2-15 6.4 0 11.3 3.9 13.3 9.3h16.4c-2.6-13.4-14.4-23.3-29.6-23.3-17.3 0-30.3 13.1-30.3 29.2v.2c0 16.1 12.8 29 30.1 29 14.8 0 26.4-9.6 29.4-22.4zm-97.9-40.1L348.2 145l-7.4-3.2-175.5 1.3v89l225.8.1z" fill="@{text}"/><path d="M313 224c2.1-7.2 1.3-13.8-2.2-18.7-3.2-4.5-8.6-7.1-15.1-7.4l-123.1-1.6c-.8 0-1.5-.4-1.9-1s-.5-1.4-.3-2.2c.4-1.2 1.6-2.1 2.9-2.2l124.2-1.6c14.7-.7 30.7-12.6 36.3-27.2l7.1-18.5c.3-.8.4-1.6.2-2.4-8-36.2-40.3-63.2-78.9-63.2-35.6 0-65.8 23-76.6 54.9-7-5.2-15.9-8-25.5-7.1-17.1 1.7-30.8 15.4-32.5 32.5-.4 4.4-.1 8.7.9 12.7-27.9.8-50.2 23.6-50.2 51.7 0 2.5.2 5 .5 7.5.2 1.2 1.2 2.1 2.4 2.1h227.2c1.3 0 2.5-.9 2.9-2.2zm39.2-79.1c-1.1 0-2.3 0-3.4.1-.8 0-1.5.6-1.8 1.4l-4.8 16.7c-2.1 7.2-1.3 13.8 2.2 18.7 3.2 4.5 8.6 7.1 15.1 7.4l26.2 1.6c.8 0 1.5.4 1.9 1s.5 1.5.3 2.2c-.4 1.2-1.6 2.1-2.9 2.2l-27.3 1.6c-14.8.7-30.7 12.6-36.3 27.2l-2 5.1c-.4 1 .3 2 1.4 2h93.8c1.1 0 2.1-.7 2.4-1.8 1.6-5.8 2.5-11.9 2.5-18.2 0-37.1-30.1-67.2-67.3-67.2" fill="@{peach}"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    pre,
    code {
      background-color: @mantle;
      color: @text;
      border-color: @surface0;
    }

    thead tr {
      border-color: @surface0;
    }

    .bitcoinAddress {
      background-color: @mantle;
      color: @text;
    }

    .bg-info {
      background-color: @mantle;
      color: @text;
    }

    .subscriptions {
      .rpm10 {
        border-color: @teal;

        h4,
        h5,
        .price {
          background-color: @teal;
          color: @base;
        }
      }

      .rpm50 {
        border-color: @green;

        h4,
        h5,
        .price {
          background-color: @green;
          color: @base;
        }
      }

      .rpm100 {
        border-color: @yellow;

        h4,
        h5,
        .price {
          background-color: @yellow;
          color: @base;
        }
      }

      .rpm500 {
        border-color: @peach;

        h4,
        h5,
        .price {
          background-color: @peach;
          color: @base;
        }
      }

      .description {
        color: @text;
      }
    }

    .finePrint {
      color: @text;
    }

    .table-bordered {
      &,
      th,
      td {
        border-color: @surface0;
      }
    }

    .dropdown-menu {
      background-color: @base;

      > li > a {
        &:hover,
        &:focus {
          background-color: @mantle;
        }
      }
    }

    @media (min-width: 768px) {
      ul.nav li.dropdown:hover {
        background-color: @base;
      }
    }

    @media (max-width: 480px) {
      #searchContainer {
        background-color: @mantle;
      }
    }
  }
}

/* ==UserStyle==
@name Snapchat Web Catppuccin
@namespace github.com/catppuccin/userstyles/styles/snapchat-web
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/snapchat-web
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/snapchat-web/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Asnapchat-web
@description Soothing pastel theme for Snapchat Web
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document url-prefix("https://www.snapchat.com/web") {
  :root[theme="dark"] {
    #catppuccin(@darkFlavor);
  }
  :root[theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    /* Snapchat applies the variables (overrides?) to specific elements so we need to apply to every element (with high specificity) to override those. */
    &,
    body > main#root * {
      --sigMain: @base;
      --sigSurface: @mantle;
      --sigSurfaceRGB: red(@mantle), green(@mantle), blue(@mantle);
      --sigAboveSurface: @crust;
      --sigSurfaceDown: @base;
      --sigSubscreen: @crust;
      --sigTextField: @crust;
      --sigDivider: @surface0;
      --sigDividerLight: @surface0;
      --sigColorBackgroundBorder: @surface0;
      --sigBackgroundPrimary: @base;
      --sigBackgroundSecondary: @mantle;
      --sigBackgroundSecondaryHover: darken(@mantle, 5%);
      --sigBackgroundTertiary: @crust;
      --sigBackgroundMessageHover: @surface1;
      --sigBackgroundMessageSaved: @surface0;
      --sigBackgroundMessageSavedHover: @surface2;
      --sigOverlay: fade(@surface1, 40%);
      --sigOverlayHover: fade(@surface1, 35%);
      --sigBrandSecondary: @accent;
      --sigObject: rgba(255, 255, 255, 0.05);

      --sigTextPrimary: @text;
      --sigButtonOnPrimary: @crust;
      --sigTextSecondary: @subtext0;
      --sigButtonOnSecondary: @subtext0;
      --sigTextTertiary: @subtext1;
      --sigButtonOnTertiary: @subtext1;
      --sigTextNegative: @red;
      --sigButtonOnSuccess: @base;
      --sigButtonOnError: @base;
      --sigButtonOnNegative: @base;
      --sigButtonOnChatSurfaceCalling: @base;
      --sigTextPlayer: @crust;
      --sigButtonGreyHover: darken(@surface0, 5%);
      --sigButtonGreyActive: darken(@surface0, 8%);

      --sigButtonPrimary: @accent;
      --sigButtonPrimaryHover: darken(@accent, 5%);
      --sigButtonPrimaryActive: darken(@accent, 8%);
      --sigButtonSecondary: @surface0;
      --sigButtonSecondaryHover: @surface1;
      --sigButtonSecondaryActive: @surface2;
      --sigButtonNegative: @red;
      --sigButtonError: @red;
      --sigButtonErrorHover: darken(@red, 5%);
      --sigButtonSuccess: @green;
      --sigButtonSuccessHover: darken(@green, 5%);
      --sigIconCalling: @green;
      --sigIconCallingHover: darken(@green, 5%);
      --sigChatSurfaceCalling: @green;
      --sigChatSurfaceCallingDisabled: darken(@green, 20%);
      --sigChatSurfaceCallingHover: darken(@green, 5%);

      --sigChat: @blue;
      --sigChatIcon: @blue;
      --sigSnapWithoutSound: @red;
      --sigSnapWithSound: @mauve;
    }

    // new chat button
    button[title="New Chat"],
    // checkbox to choose camera
    [id*="downshift-"] a,
    // checkbox in new chat popup
    [aria-label="Unselect chosen user"] {
      path[fill="#fff"] {
        fill: @crust;
      }
      // replaces blue fill
      path[fill="#51B7FF"] {
        fill: @accent;
      }
    }

    // new group button
    form > div > div > div[role="searchbox"] button {
      color: @crust;
      path {
        fill: @crust;
      }
    }

    // story reply text
    li button[type="button"].replyText {
      background-color: rgba(30, 30, 30, 0.8);
    }

    // buttons when in call
    [data-projection-id] button {
      --sigColorAlwaysWhite: @surface0;
    }

    // replay button on stories
    img[role="presentation"][src^="blob:"] + div > svg > path[fill="#fff"] {
      fill: @text;
    }
  }
}

/* ==UserStyle==
@name Modrinth Catppuccin
@namespace github.com/catppuccin/userstyles/styles/modrinth
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/modrinth
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/modrinth/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Amodrinth
@description Soothing pastel theme for Modrinth
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("modrinth.com") {
  .light,
  .light-mode,
  .light-properties,
  html {
    #catppuccin(@lightFlavor);
  }

  .dark,
  .dark-mode,
  .oled-mode,
  :root[data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    // TODO: Use Catppuccin palette colors? `fade()`-ed?
    @shadow: if(@flavor = latte, #dbdfef, #010409);

    #css-variables() !important;

    // homepage
    .blob-demonstration,
    .blob-demonstration::after {
      background: linear-gradient(
        0deg,
        fade(@accent, 20%),
        fade(@base, 10%)
      ) !important;
    }
    .logo-banner path {
      fill: @accent !important;
    }
    .logo-banner > svg > g > rect {
      display: none;
    }

    [tabindex="0"]:focus-visible,
    a:focus-visible,
    button:focus-visible {
      outline-color: @accent;
    }

    .BDVE3s9MFQttmbMUeYup-2 a b,
    .BDVE3s9MFQttmbMUeYup-2 a strong {
      color: @accent;
    }

    // dropdown icon
    .multiselect__select::before {
      border-color: @text transparent transparent;
      color: @text;
    }
    // header button hover
    .btn-wrapper:hover {
      a,
      button {
        --tw-brightness: none !important;
      }
    }
    .nuxt-loading-indicator {
      background: @accent !important;
    }

    #css-variables() {
      --text-color: @text;
      --color-base: @text;
      --color-bg: @crust;
      --color-secondary: @subtext0;
      --color-ad-raised: @surface2;
      --color-ad: @surface1;
      --color-ad-highlight: @teal;
      --color-brand: @accent;
      --color-brand-green: @green;
      --color-button-bg-active: @overlay0;
      --color-button-bg-selected: fade(@accent, 25%);
      --color-button-bg-hover: @surface1;
      --color-button-bg: @surface0;
      --color-button-text-hover: @text;
      --color-button-text: @subtext1;
      --color-button-text-active: @text;
      --color-button-text-selected: @accent;
      --color-divider: @surface0;
      --color-divider-dark: @surface2;
      --color-heading: @text;
      --color-icon: @text;
      --color-link-active: @sapphire;
      --color-link-hover: @sky;
      --color-link: @blue;
      --color-raised-bg: @base;
      --color-blue: @sapphire;
      --color-special-blue: @sapphire;
      --color-orange: @peach;
      --color-special-orange: @peach;
      --color-purple: @mauve;
      --color-special-purple: @mauve;
      --color-red: @red;
      --color-gray: @subtext0;
      --color-special-gray: @subtext0;
      --color-green: @green;
      --color-text: @subtext1;
      --color-text-dark: @text;
      --color-text-inactive: @overlay1;
      --color-brand-highlight: fade(@accent, 25%);
      --color-brand-inverted: @shadow;
      --color-table-alternate-row: @crust;
      --color-table-border: @overlay0;
      --color-contrast: @text;
      --color-accent-contrast: @mantle;
      --color-red-highlight: fade(@red, 25%);
      --color-orange-highlight: fade(@peach, 25%);
      --color-green-highlight: fade(@accent, 25%);
      --color-blue-highlight: fade(@blue, 25%);
      --color-purple-highlight: fade(@mauve, 25%);
      --color-gray-highlight: fade(@text, 25%);
      --color-red-bg: fade(@red, 20%);
      --color-orange-bg: fade(@peach, 25%);
      --color-green-bg: fade(@accent, 25%);
      --color-blue-bg: fade(@blue, 25%);
      --color-purple-bg: fade(@mauve, 25%);
      --color-brand-shadow: @accent;
      --color-warning-banner-side: @red;
      --color-warning-banner-bg: fade(@red, 25%);
      --color-warning-banner-text: @text;
      --color-platform-fabric: @rosewater;
      --color-platform-quilt: @mauve;
      --color-platform-forge: @lavender;
      --color-platform-neoforge: @peach;
      --color-platform-liteloader: @sky;
      --color-platform-bukkit: @peach;
      --color-platform-bungeecord: @yellow;
      --color-platform-folia: @green;
      --color-platform-paper: @red;
      --color-platform-purpur: @mauve;
      --color-platform-spigot: @yellow;
      --color-platform-velocity: @teal;
      --color-platform-waterfall: @blue;
      --color-platform-sponge: @yellow;
      --color-platform-ornithe: @teal;
      --color-platform-bta-babric: @green;
      --color-platform-legacy-fabric: @lavender;
      --color-platform-nilloader: @pink;
      --color-button-border: fade(@crust, 20%);
      --color-tooltip-bg: @surface1;
      --color-tooltip-text: @subtext1;
      --landing-green-label: @accent;
      --landing-green-label-bg: fade(@accent, 10%);
      --landing-blue-label: @blue;
      --landing-color-heading: @text;
      --landing-color-subheading: @subtext0;
      --landing-border-color: @overlay0;
      --landing-blue-label-bg: fade(@blue, 10%);
      --landing-border-gradient: linear-gradient(
        to bottom right,
        @overlay0,
        @surface2
      );
      --brand-gradient-strong-bg: linear-gradient(
        270deg,
        fade(@accent, 5%) 10%,
        fade(@accent, 15%)
      );
      --brand-gradient-border: fade(@accent, 10%);

      --surface-1: @crust;
      --surface-1-5: mix(@crust, @mantle, 50%);
      --surface-2: @mantle;
      --surface-2-5: mix(@mantle, @base, 50%);
      --surface-3: @base;
      --surface-4: @surface0;
      --surface-5: @surface2;

      --color-text-primary: @text;
      --color-text-default: @subtext1;
      --color-text-tertiary: @subtext0;
    }
  }
}

/* ==UserStyle==
@name 7TV Catppuccin
@namespace github.com/catppuccin/userstyles/styles/seventv
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/seventv
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/seventv/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aseventv
@description Soothing pastel theme for 7TV
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("7tv.app") {
  .light-theme {
    #catppuccin(@lightFlavor);
  }
  .dark-theme {
    #catppuccin(@darkFlavor);
  }

  .system-theme {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    background-color: @base;

    --secondary: @surface0;
    --secondary-text: @text;
    --secondary-hover: @surface0;
    --secondary-active: @surface0;
    --secondary-disabled: @crust;
    --secondary-border: transparent;
    --primary: @accent;
    --primary-text: @crust;
    --primary-hover: darken(@accent, 5%);
    --primary-active: darken(@accent, 5%);
    --primary-disabled: @subtext0;
    --primary-border: transparent;
    --bg-dark: @crust;
    --bg-medium: @mantle;
    --bg-light: @base;
    --text: @text;
    --text-light: @subtext0;
    --layout-border: transparent;
    --border-active: @base;
    --store: @mauve;
    --preview: @mantle;
    --danger: @peach;
    --approve: @green;
    --rename: @sapphire;
    --staff: @red;
    --staff-bg: fade(@red, 20%);
    --admin-merge: @mauve;
    --admin-unlist: @peach;

    .flag {
      &[style*="#57ab5a"] {
        color: @green !important;
        background-color: fade(@green, 20%) !important;
      }
      /* Emote is in selected emote set */
      &[style*="#529bf5"] {
        color: @accent !important;
        background-color: fade(@accent, 20%) !important;
      }
      /* Emote is unlisted */
      &[style*="#eb3d26"] {
        color: @red !important;
        &[style*="background-color"] {
          background-color: fade(@red, 20%) !important;
        }
      }
      /* Emote is trending */
      &[style*="#e0823d"] {
        color: @peach !important;
        &[style*="background-color"] {
          background-color: fade(@peach, 20%) !important;
        }
      }
      /* Emote is overlaying */
      &[style*="#fc8dc7"] {
        color: @pink !important;
        &[style*="background-color"] {
          background-color: fade(@pink, 20%) !important;
        }
      }
      /* Personal emote set */
      &[style*="#b083f0"] {
        color: @mauve !important;
      }
    }

    .badge {
      color: @base;
    }

    .emote,
    .emote-set {
      /* Emote is in selected emote set */
      &[style*="--highlight-active: #529bf5"] {
        --highlight: fade(@accent, 80%) !important;
        --highlight-active: @accent !important;
        &.emote-set .name {
          color: @accent !important;
        }
      }

      /* Emote is unlisted */
      &[style*="--highlight-active: #eb3d26"] {
        --highlight: fade(@red, 80%) !important;
        --highlight-active: @red !important;
      }

      /* Emote is trending */
      &[style*="--highlight-active: #e0823d"] {
        --highlight: fade(@peach, 80%) !important;
        --highlight-active: @peach !important;
      }

      /* Emote is overlaying */
      &[style*="--highlight-active: #fc8dc7"] {
        --highlight: fade(@pink, 80%) !important;
        --highlight-active: @pink !important;
      }

      /* Emote set is a personal emote set */
      &.emote-set[style*="--highlight-active: #b083f0"] {
        --highlight: fade(@mauve, 80%) !important;
        --highlight-active: @mauve !important;
        &.emote-set .name {
          color: @mauve !important;
        }
      }

      /* Emote set is a special emote set */
      &.emote-set[style*="--highlight-active: #fcc200"] {
        --highlight: fade(@yellow, 80%) !important;
        --highlight-active: @yellow !important;
        &.emote-set .name,
        &.emote-set .flag {
          color: @yellow !important;
        }
      }
    }

    img.image,
    .profile-picture,
    .profile-name .name,
    .user,
    .user-link,
    .username .name,
    .role > span,
    .side-bar .name,
    .roles > span {
      /* Admin */
      &[style*="255, 70, 70"] {
        &,
        span,
        img {
          color: @red !important;
          border-color: @red !important;
        }
      }

      /* Moderator */
      &[style*="50, 168, 82"] {
        &,
        span,
        img {
          color: @green !important;
          border-color: @green !important;
        }
      }

      &[style*="23, 235, 182"],
      &[style*="177, 235, 52"],
      &[style*="68, 194, 135"] {
        &,
        span {
          color: @teal !important;
          border-color: @teal !important;
        }
      }
      /* Event coordinator */
      &[style*="182, 56, 181"] {
        &,
        span,
        img {
          color: @pink !important;
          border-color: @pink !important;
        }
      }

      /* Verified */
      &[style*="145, 70, 255"] {
        &,
        span,
        img {
          color: @mauve !important;
          border-color: @mauve !important;
        }
      }
      /* Subscriber */
      &[style*="255, 170, 0"] {
        &,
        span,
        img {
          color: @yellow !important;
          border-color: @yellow !important;
        }
      }
    }

    .hero {
      svg {
        color: @text !important;
      }

      color: @text;
      .for-all {
        -webkit-text-stroke-color: @text !important;
      }

      &::before {
        background:
          radial-gradient(
            180% 80% at 0% 100%,
            @text 0%,
            @blue 25%,
            fade(@mauve, 90%) 56%,
            fade(@mauve, 50%) 79%,
            transparent 100%
          ),
          @crust;
      }
    }

    /* Sub progress bar */

    .progress-circle {
      #progress {
        stroke: @accent;
      }
    }

    .subgrid .badge {
      color: @subtext0 !important;
    }

    /* Subscribe gradients */
    .gradient {
      color: @text !important;

      &.g1 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @peach,
            @yellow 1%,
            @yellow 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }

      &.g2 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @text,
            @red 1%,
            @red 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }

      &.g3 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @peach,
            @pink 1%,
            @mauve 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }

      &.g5 {
        background:
          radial-gradient(
            150% 180% at 50% 180%,
            @peach,
            @sapphire 1%,
            @sapphire 25%,
            @mantle 75%
          ),
          var(--secondary) !important;
      }
    }

    /* Home page glow */
    .weird-smiley::before,
    .feature .background {
      background-image: radial-gradient(
        circle at bottom,
        fade(@mauve, 20%),
        fade(@sapphire, 20%)
      ) !important;
    }

    .banner {
      color: @base;

      &[style="--gradient-color: #9227cf"] {
        --gradient-color: @mauve !important;
      }
      &[style="--gradient-color: #27cfb1"] {
        --gradient-color: @teal !important;
      }
      &[style="--gradient-color: #ff11bc"] {
        --gradient-color: @red !important;
      }

      &::before {
        background:
          radial-gradient(
            100% 100% at 50% 0%,
            @text 0%,
            var(--gradient-color) 33%,
            @mauve 64%,
            fade(@mauve, 50%) 80%,
            @mantle 100%
          ),
          var(--bg-medium) !important;
      }
    }

    /* Sub badge progress bar */

    progress[value].bar {
      &::-webkit-progress-bar,
      &::-moz-progress-bar {
        background: @accent !important;
      }
    }
  }
}
@-moz-document domain("twitch.tv") {
  .tw-root--theme-dark {
    #catppuccin(@darkFlavor);
  }
  .tw-root--theme-light {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();

    --seventv-text-color-normal: @text;
    --seventv-text-color-secondary: @subtext0;

    --seventv-border-transparent-1: @surface0;
    --seventv-background-shade-1: @base;
    --seventv-background-shade-2: @mantle;
    --seventv-background-shade-3: @crust;
    --seventv-background-transparent-1: @base;
    --seventv-background-transparent-2: @mantle;
    --seventv-background-transparent-3: @mantle;
    --seventv-highlight-neutral-1: @surface0;
    --seventv-input-background: @mantle;
    --seventv-input-border: @surface0;
    --seventv-subscriber-color: @yellow;

    --seventv-highlight-color: @accent;
    --seventv-highlight-dim-color: fade(@accent, 20%);

    --seventv-primary: @accent;
    --seventv-accent: @green;
    --seventv-warning: @peach;
    --seventv-muted: @subtext0;

    .seventv-transparent {
      --seventv-border-transparent-1: fade(@surface0, 77%);
      --seventv-background-transparent-1: fade(@base, 77%);
      --seventv-background-transparent-2: fade(@mantle, 59%);
      --seventv-background-transparent-3: fade(@mantle, 71%);
    }

    .seventv-announce-message-container {
      .announce-header {
        background-color: @crust;
      }
      .announce-message {
        background-color: @base;
      }
    }

    .grabbable-inner, .grabbable-outer {
      --color-border-input: @subtext0;
    }

    .seventv-user-message {
      /* First time chatter */
      &[style*="--seventv-highlight-color: #c832c8"] {
        --seventv-highlight-color: @mauve !important;
        --seventv-highlight-dim-color: fade(@mauve, 10%) !important;
      }
      /* Mention */
      &[style*="--seventv-highlight-color: #e13232"] {
        --seventv-highlight-color: @red !important;
        --seventv-highlight-dim-color: fade(@red, 10%) !important;
      }
      /* Blocked */
      &[style*="--seventv-highlight-color: #9488855A"] {
        --seventv-highlight-color: @surface0 !important;
      }
      /* Raider */
      &[style*="--seventv-highlight-color: #6dd126"] {
        --seventv-highlight-color: @green !important;
        --seventv-highlight-dim-color: fade(@green, 10%) !important;
      }
      /* Returning chatter */
      &[style*="--seventv-highlight-color: #3296e6"] {
        --seventv-highlight-color: @blue !important;
        --seventv-highlight-dim-color: fade(@blue, 10%) !important;
      }
    }

    .seventv-chat-message-container:hover .seventv-chat-message-background {
      background-color: @surface0;
    }

    .seventv-sub-message-container, .seventv-reward-message-container {
      background-color: @base;
    }

    .seventv-settings-category {
      .seventv-settings-category-dropdown .seventv-settings-subcategory {
        &:hover {
          background-color: @base !important;
        }
        &.intersect {
          background-color: @surface0 !important;
        }
      }

      .settings-category-header {
        &:hover, &:focus-within {
          background-color: @base;
        }
      }
    }

    .seventv-settings-category[in-view="true"] > .settings-category-header {
      background-color: @surface0;
    }

    .paint-tool-home {
      h6[style="color: red;"] {
        color: @peach !important;
      }
    }

    section[timeline-id="LIVE"] {
      label, div[selector="date-boundary"] {
        color: @red;
        border-color: @red;
      }
    }

    .seventv-emote-container[zero-width="true"] {
      border-color: @yellow;
    }

    .scope-labels {
      .label-global {
        color: @green;
      }
      .label-sub-feature {
        color: @yellow;
      }
    }

    [style*="rgb(255, 255, 255)"] .seventv-chat-user-username span {
      color: @text !important;
    }

    .seventv-chat-mod-buttons {
      color: @subtext0;

      svg:hover {
        color: @text;
      }
    }
  }
}

/* ==UserStyle==
@name Ollama Catppuccin
@namespace github.com/catppuccin/userstyles/styles/ollama
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/ollama
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/ollama/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aollama
@description Soothing pastel theme for Ollama
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("ollama.com") {
  @import url("https://unpkg.com/@catppuccin/highlightjs@1.0.0/css/catppuccin-variables.css");

  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    background-color: @base;
    color: @text;

    /* Llama logos */
    img[src="/public/ollama.png"],
    img[src="/public/shades.png"],
    img[src="/public/glasses.png"] {
      filter: @text-filter;
    }

    code,
    pre {
      background-color: @mantle;
      color: @text !important;
    }

    input {
      background-color: @mantle;
    }

    main,
    section,
    strong,
    h3,
    ul,
    button,
    li,
    li::marker {
      color: @text;
    }
    blockquote {
      color: @subtext0;
    }

    a[class~=""] {
      color: @blue;
    }

    #query,
    #filter,
    #search {
      background-color: @mantle;
      color: @text;
    }
    #readme,
    #display,
    #file-explorer {
      color: @text;
    }

    .command {
      color: @text;
    }
    .truncate {
      color: @text;
    }

    /* Tailwind */

    * {
      border-color: @surface1;
    }

    .prose {
      --tw-prose-headings: @text;
      --tw-prose-links: @accent;
    }

    .text-white,
    .text-black {
      color: @text;
    }
    .text-gray-900 {
      color: @subtext1;
    }
    .text-green-500,
    .text-emerald-500,
    .text-green-700 {
      color: @green;
    }
    .text-yellow-900 {
      color: @yellow;
    }
    .text-neutral-300,
    .text-neutral-400,
    .text-neutral-500 {
      color: @subtext0;
    }
    .text-neutral-700,
    .text-neutral-800,
    .text-neutral-900 {
      color: @subtext1 !important;
    }
    .text-red-500 {
      color: @red;
    }
    .text-blue-500,
    .text-blue-600 {
      color: @accent;
    }
    /* Models page, color for non-weight pills/tags. Background color is solid from `.bg-indigo-50`. */
    .text-indigo-600 {
      color: @crust;
    }

    .bg-neutral-100 pre,
    .bg-neutral-100 .command {
      background-color: unset !important;
    }
    .bg-white {
      background-color: @mantle;
    }
    .bg-black,
    .hover\:bg-black:hover {
      background-color: @surface0 !important;
    }
    .bg-neutral-50 {
      background-color: @surface0;
    }
    .bg-neutral-100,
    .hover\:bg-neutral-100:hover {
      background-color: @surface2 !important;
    }
    .bg-neutral-700,
    .bg-neutral-800 {
      background-color: @surface1;
    }
    .bg-green-50 {
      background-color: fade(@green, 10%);
    }
    .bg-yellow-50 {
      background-color: fade(@yellow, 10%);
    }
    .bg-indigo-50 {
      background-color: @accent;
    }
    .bg-\[\#ddf4ff\] {
      background-color: fade(@accent, 10%);
    }

    .border {
      border-color: @accent;
    }
    .border-neutral-200,
    .border-neutral-300,
    .divide-gray-200 > :not([hidden]) ~ :not([hidden]),
    .divide-neutral-200 > :not([hidden]) ~ :not([hidden]) {
      border-color: @surface1;
    }
    .focus\:border-blue-400:focus {
      border-color: @accent;
    }
    .focus\:border-red-400:focus {
      border-color: @red;
    }

    .ring-neutral-300 {
      --tw-ring-color: @surface1 !important;
    }
    .ring-green-600\/20 {
      --tw-ring-color: @green;
    }
    .ring-yellow-600\/20 {
      --tw-ring-color: @yellow;
    }
    select:focus,
    .ring-blue-300,
    .focus\:ring-blue-300:focus {
      --tw-ring-color: rgba(#lib.rgbify(@accent)[], var(--tw-ring-opacity));
    }
    .focus\:ring-red-300:focus {
      --tw-ring-color: rgba(#lib.rgbify(@red)[], var(--tw-ring-opacity));
    }
  }
}

