        color: @base;
        text-shadow: none;
      }
      button:not(.custom),
      .btn {
        background: @surface0;
        text-shadow: none;
        color: @text;
      }
      .item.zmyc33:hover,
      .item.active.zmyc33 {
        background-color: @surface0;
      }
      .video-title.damcrq,
      .logo-text.c1j5psx1.c1j5psx1 {
        color: @text;
      }
      [d="M 4,0 1,3 v 10 h 4 v 3 l 3,-3 h 2 L 15,8 V 0 Z m 10,7 -3,3 H 9 L 7,12 V 10 H 5 V 1 h 9 z"],
      [d="m 8.5,3 3,2 -3,2 z"] {
        fill: @accent;
      }
      [d="m 4,1 h 10 v 7 l -4,4 H 4 Z"] {
        fill: @base;
      }
      .delete.c19loos5.c19loos5 {
        border-color: @red;
      }
      .mark.z8oy0d.z8oy0d {
        background: @accent;
        color: @base;
      }
      .bg.c1ejz165.c1ejz165 {
        opacity: @bg-opacity;
        filter: blur(@bg-blur);
      }
      // .topbar-container.c1j5psx1.c1j5psx1 {
      //   border-bottom: none;
      // }
      #inner-a.tmgko.tmgko {
        background: @mantle;
      }
    }
  }
}

