      @raw_before: '<svg xmlns="http://www.w3.org/2000/svg" width="19" height="18" viewBox="0 0 24 25" fill="%COLOR%"><path d="M18 20h2v3c0 1-1 2-2 2H2c-.998 0-2-1-2-2V5c0-.911.755-1.667 1.667-1.667h5A3.323 3.323 0 0 1 10 0a3.323 3.323 0 0 1 3.333 3.333h5A1.68 1.68 0 0 1 20 5v8.333h-2V9H2v14h16zM3 7h14c0-.911-.793-1.667-1.75-1.667H13.5c-.957 0-1.75-.755-1.75-1.666C11.75 2.755 10.957 2 10 2s-1.75.755-1.75 1.667c0 .911-.793 1.666-1.75 1.666H4.75C3.793 5.333 3 6.09 3 7"/><path d="M4 19h6v2H4zm8-8H4v2h8zm-8 6h4v-2H4zm11-2v-3l-4.5 4.5L15 21v-3l8.027-.032L23 15z"/></svg>';

      > img {
        @svg: escape(replace(@raw, "%COLOR%", @subtext0));
        content: url("data:image/svg+xml,@{svg}");
        filter: none;
      }
      &:hover > img {
        @svg: escape(replace(@raw, "%COLOR%", @text));
        content: url("data:image/svg+xml,@{svg}");
        filter: none;
      }

      &:not(:has(> img)) {
        &::before {
          @svg: escape(replace(@raw_before, "%COLOR%", @subtext0));
          content: url("data:image/svg+xml,@{svg}");
          filter: none;
        }

        &:hover::before {
          @svg: escape(replace(@raw_before, "%COLOR%", @text));
          content: url("data:image/svg+xml,@{svg}");
          filter: none;
        }
      }
    }

    details.toggle {
      @plus: escape(
        '<svg width="17" height="17" shape-rendering="crispEdges" stroke="@{text}" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 2.5H2.5v12H5m7-12h2.5v12H12m-7-6h7M8.5 12V5"/></svg>'
      );
      @minus: escape(
        '<svg width="17" height="17" shape-rendering="crispEdges" stroke="@{text}" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 2.5H2.5v12H5m7-12h2.5v12H12m-7-6h7"/></svg>'
      );

      > summary::before {
        background: url("data:image/svg+xml,@{plus}") no-repeat top left;
        filter: none;
      }

      &[open] > summary::before {
        background: url("data:image/svg+xml,@{minus}") no-repeat top left;
      }
    }

    .src #sidebar-button > a::before {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 22 22" fill="none" stroke="@{text}"><path d="M16 9V5h-6V4L8 2H4L2 4v16h13l6-11H6L2 19" stroke-width="1.25"/><path d="M15 7H4v3" stroke-width=".75"/><path d="M3.75 10v1.25" stroke-width=".375"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    .pure-menu-link {
      color: @subtext0;

      &:hover {
        color: @text;
      }
    }
    .pure-table {
      &,
      td,
      th {
        border-color: @surface0;
      }
    }
  }
}

/* ==UserStyle==
@name Porkbun Catppuccin
@namespace github.com/catppuccin/userstyles/styles/porkbun
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/porkbun
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/porkbun/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aporkbun
@description Soothing pastel theme for Porkbun
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("porkbun.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    &,
    body {
      background-color: @base;
      color: @text;
    }

    --cloudflare_on: @peach;
    --porkbun_danger: @red;
    --porkbun_warning: @yellow;
    --porkbun_success: @green;
    --porkbun_pink_hover: darken(@accent, 5%);
    --porkbun_pink: @accent;
    --porkbun_gold: @yellow;
    --porkbun_pink_light: lighten(@accent, 5%);
    --porkbun_pink_medium: @accent;
    --porkbun_dark_gray: @text;
    --porkbun_light_gray: @surface0;
    --porkbun_medium_gray: @overlay1;
    --porkbun_white: @mantle;
    --blue_link: @blue;
    --blue_link_hover: @sapphire;
    --headerMenuLink_color: @text;
    --headerMenuLink-hover_color: @text;
    --homepageBlurb_color: @text;

    /* Misc */

    .text-muted {
      color: @subtext0;
    }
    .text-danger {
      color: @red;
    }
    .text-success {
      color: @green;
    }

    .badge-porkbun {
      background-color: @surface0;
      color: @text;
    }

    .alert-info {
      background-color: fade(@blue, 30%);
      color: @blue;
      border-color: @blue;
    }

    .alert-warning {
      background-color: fade(@yellow, 30%);
      color: @yellow;
      border-color: @yellow;
    }

    .alert-danger {
      background-color: fade(@red, 30%);
      color: @red;
      border-color: @red;
    }

    hr {
      border-top-color: @surface1;
    }

    /* Inline overrides */

    [style*="background-color:white;"],
    [style*="background-color: rgb(248, 248, 248);"] {
      background-color: @surface0 !important;
    }
    [style*="color:black;"],
    [style*="color: white;"] {
      color: @text !important;
    }

    &[stylus-iframe="https://porkbun.com"],
    #beacon-container-body {
      background-color: transparent;

      .hsds-beacon button {
        background-color: @accent;

        [class*="FabButtoncss__FabBackgroundUI"] > svg {
          fill: @accent;
        }

        > span {
          color: @crust;
        }
      }
    }

    /* Buttons */

    .btn-default,
    .sortByPriceButton {
      &:not(.searchAddRemoveIcon, .searchAddRemoveIconSideBar) {
        background-color: @surface0;
        color: @text;
        border-color: @surface1;
      }

      &:hover {
        background-color: @surface1;
        color: @text;
      }
    }

    .btn-primary {
      background-color: @accent;
      border-color: @accent;
      color: @crust;

      &:hover {
        background-color: darken(@accent, 5%);
      }
    }

    .btn-danger {
      background-color: @red;
      border-color: @red;
      color: @crust;
    }

    .btn-success {
      background-color: @green;
      border-color: @green;
      color: @crust;
    }

    .btn-success-light {
      background-color: @green;
      color: @crust;
    }

    .btn-porkbun-white-borderless,
    .btn-porkbun-white:hover,
    .btn-porkbun-white:focus {
      color: @text;
    }

    .btn-porkbun-white.active {
      color: @crust;

      .text-muted {
        color: @surface0;
      }
    }

    /* Inputs */

    .slider {
      background-color: @red;

      &::before {
        background-color: @crust;
      }
    }

    .dropdown-menu {
      background-color: @surface0;

      > li > a {
        color: @text;

        &:hover {
          background-color: @surface1;
        }
      }

      .divider {
        background-color: @surface1;
      }
    }

    .form-control {
      background-color: @mantle;
      color: @text;
      border-color: @surface0;

      &:focus {
        box-shadow: 0 0 8px fade(@accent, 50%);
      }
    }

    select:not([multiple]) {
      -webkit-appearance: auto;
    }

    /* Table dividers */

    .table {
      > tbody,
      > tfoot,
      > thead {
        > tr {
          > th,
          > td {
            border-top-color: @surface1;
          }
        }
      }

      > thead > tr > th {
        border-bottom-color: @surface2;
      }

      [style*="border-top:2px solid gray;"] {
        border-top-color: @surface2 !important;
      }
    }

    .table-bordered {
      border-color: @surface1;

      > tbody,
      > tfoot,
      > thead {
        > tr {
          > th,
          > td {
            border-color: @surface1;
          }
        }
      }
    }

    /* Main */

    .headerContainer,
    footer > div {
      background-color: @crust !important;
    }

    #headerBrandLogo,
    #footerLogo {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144" fill="@{crust}"><circle fill="@{accent}" cx="72" cy="72" r="56.3"/><path d="M43.1 43.2c5 1.1 9.8 2.9 14.1 5.3-5.1 2.6-9.4 6.5-12.5 11.3-2-2.7-3.1-6.1-3.1-9.7q0-3.75 1.5-6.9"/><path d="M102.4 95.2c0 3.1-2.5 5.6-5.6 5.6s-5.6-2.5-5.6-5.6v-4.5H52.7v4.5c0 3.1-2.5 5.6-5.6 5.6s-5.6-2.5-5.6-5.6V78.1c0-16.5 12.8-30.5 29.3-31.1 17.3-.6 31.5 13.2 31.5 30.4z"/><path d="M99.3 59.8c-3.1-4.8-7.4-8.7-12.5-11.3 4.4-2.4 9.1-4.2 14.1-5.3q1.5 3.15 1.5 6.9c0 3.6-1.2 6.9-3.1 9.7"/><path fill="@{accent}" d="M85.3 71.4c-.4-.2-.8-.1-1 .2-.4.6-.9 1-1.6 1.4v-.5c0-1.4-.5-2.7-1.3-3.7-.6-.9-1.6-1.4-2.8-1.4-1.9 0-3.5 1.6-3.5 3.5 0 .8.3 1.6.8 2.2.6.7 1.3 1.3 2.2 1.7-.6.3-1.2.5-1.9.5-.8 0-1.4.7-1.4 1.4 0 .8.6 1.4 1.4 1.4h.7c2.2 0 4.2-1.3 5.1-3.1 1.5-.4 2.7-1.4 3.5-2.7.3-.2.2-.7-.2-.9m-5.7 1.9c-.9-.3-1.7-.8-2.2-1.6-.2-.2-.3-.5-.3-.8 0-.8.6-1.4 1.4-1.4.7 0 1.4.6 1.4 1.3 0 .2.1.4.1.7.1.6-.1 1.3-.4 1.8"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    .reviewWidget {
      .googleReviewCount {
        color: @subtext1;
      }

      .fas[class*="fa-star"] {
        color: @yellow;
      }
    }

    .homepageBulletIconFontAwesome {
      color: @subtext0;
    }
    .homePageSupportOptionCenterRight {
      border-color: @surface0;
    }

    #domainSearchBulkDropButton {
      &:hover,
      &:active,
      &:target,
      &:focus {
        background-color: @surface0;
      }
    }

    #searchResultsContainer {
      background-color: transparent;

      .sideBarSearchResults {
        border-color: @surface0;
      }
    }
    .searchResultsTldLetterBox {
      border-color: @surface1;
    }

    .cartBox {
      border-color: @surface1;
    }
    .cartSummaryBoxFreeList > li::before {
      color: @subtext0;
    }

    .marketplaceRow {
      border-top-color: @surface0;
    }

    .domainsPricingAllExtensionsHeader {
      background-color: transparent;
    }

    #homePagePricingContainer {
      background-color: transparent;
    }

    .hostingBox {
      border-color: @surface0;
    }

    .well {
      background-color: @base;
      border-color: @surface0;
    }

    .modal-content {
      background-color: @base;

      .close {
        color: @text;
        opacity: 1;
      }
    }

    .nav-tabs {
      border-bottom-color: @surface0;
    }
  }
}

/* ==UserStyle==
@name Holodex Catppuccin
@namespace github.com/catppuccin/userstyles/styles/holodex
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/holodex
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/holodex/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aholodex
@description Soothing pastel theme for Holodex
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("holodex.net") {
  :root:has(.theme--dark) {
    #catppuccin(@darkFlavor);
  }

  :root:has(.theme--light) {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --v-anchor-base: @accent;
    --v-primary-base: @accent;
    --v-primary-lighten1: lighten(@accent, 4%);
    --v-primary-lighten2: lighten(@accent, 8%);
    --v-primary-lighten3: lighten(@accent, 9%);
    --v-primary-lighten4: lighten(@accent, 18%);
    --v-primary-lighten5: lighten(@accent, 19%);
    --v-primary-darken1: darken(@accent, 14%);
    --v-primary-darken2: darken(@accent, 31%);
    --v-primary-darken3: darken(@accent, 35%);
    --v-primary-darken4: darken(@accent, 43%);

    --v-accent-base: @accent;
    --v-accent-lighten1: lighten(@accent, 4%);
    --v-accent-lighten2: lighten(@accent, 8%);
    --v-accent-lighten3: lighten(@accent, 9%);
    --v-accent-lighten4: lighten(@accent, 18%);
    --v-accent-lighten5: lighten(@accent, 19%);
    --v-accent-darken1: darken(@accent, 14%);
    --v-accent-darken2: darken(@accent, 31%);
    --v-accent-darken3: darken(@accent, 35%);
    --v-accent-darken4: darken(@accent, 43%);

    --v-secondary-base: @accent;
    --v-secondary-lighten1: lighten(@accent, 4%);
    --v-secondary-lighten2: lighten(@accent, 8%);
    --v-secondary-lighten3: lighten(@accent, 9%);
    --v-secondary-lighten4: lighten(@accent, 18%);
    --v-secondary-lighten5: lighten(@accent, 19%);
    --v-secondary-darken1: darken(@accent, 14%);
    --v-secondary-darken2: darken(@accent, 31%);
    --v-secondary-darken3: darken(@accent, 35%);
    --v-secondary-darken4: darken(@accent, 43%);

    --v-error-base: @red;
    --v-error-lighten1: lighten(@red, 4%);
    --v-error-lighten2: lighten(@red, 8%);
    --v-error-lighten3: lighten(@red, 9%);
    --v-error-lighten4: lighten(@red, 18%);
    --v-error-lighten5: lighten(@red, 19%);
    --v-error-darken1: darken(@red, 14%);
    --v-error-darken2: darken(@red, 31%);
    --v-error-darken3: darken(@red, 35%);
    --v-error-darken4: darken(@red, 43%);

    --v-info-base: @blue;
    --v-info-lighten1: lighten(@blue, 4%);
    --v-info-lighten2: lighten(@blue, 8%);
    --v-info-lighten3: lighten(@blue, 9%);
    --v-info-lighten4: lighten(@blue, 18%);
    --v-info-lighten5: lighten(@blue, 19%);
    --v-info-darken1: darken(@blue, 14%);
    --v-info-darken2: darken(@blue, 31%);
    --v-info-darken3: darken(@blue, 35%);
    --v-info-darken4: darken(@blue, 43%);

    --v-success-base: @green;
    --v-success-lighten1: lighten(@green, 4%);
    --v-success-lighten2: lighten(@green, 8%);
    --v-success-lighten3: lighten(@green, 9%);
    --v-success-lighten4: lighten(@green, 18%);
    --v-success-lighten5: lighten(@green, 19%);
    --v-success-darken1: darken(@green, 14%);
    --v-success-darken2: darken(@green, 31%);
    --v-success-darken3: darken(@green, 35%);
    --v-success-darken4: darken(@green, 43%);

    --v-warning-base: @yellow;
    --v-warning-lighten1: lighten(@yellow, 4%);
    --v-warning-lighten2: lighten(@yellow, 8%);
    --v-warning-lighten3: lighten(@yellow, 9%);
    --v-warning-lighten4: lighten(@yellow, 18%);
    --v-warning-lighten5: lighten(@yellow, 19%);
    --v-warning-darken1: darken(@yellow, 14%);
    --v-warning-darken2: darken(@yellow, 31%);
    --v-warning-darken3: darken(@yellow, 35%);
    --v-warning-darken4: darken(@yellow, 43%);

    --v-background-base: @base;
    --v-background-lighten1: lighten(@base, 4%);
    --v-background-lighten2: lighten(@base, 8%);
    --v-background-lighten3: lighten(@base, 9%);
    --v-background-lighten4: lighten(@base, 18%);
    --v-background-lighten5: lighten(@base, 19%);
    --v-background-darken1: darken(@base, 14%);
    --v-background-darken2: darken(@base, 31%);
    --v-background-darken3: darken(@base, 35%);
    --v-background-darken4: darken(@base, 43%);

    div.v-application {
      background: @base !important;
      color: @text;
    }

    header#top-bar,
    header.v-toolbar,
    div.v-navigation-drawer__content,
    div#bottom-bar,
    div.v-main__wrap > div,
    div.v-select__selections,
    div.v-slide-group__wrapper,
    div.v-bottom-navigation,
    div.v-select__slot,
    div.v-input__slot,
    div.v-overlay__scrim {
      background: @base !important;
    }
    div.v-sheet {
      background: @base;
      border-color: @base;
    }

    .v-btn.v-btn--has-bg:not(.nav-btn) {
      background-color: @surface0 !important;
    }

    .v-list,
    .v-list-item,
    .v-card,
    .v-sheet,
    .v-select__selections,
    .v-label,
    .text--secondary,
    .v-input__slot input {
      color: @text !important;
      path:not([fill*="iid-1"]) {
        fill: @text;
      }
    }

    .v-messages,
    .v-list-item__subtitle,
    .v-tab:not(.v-tab--active) {
      color: @subtext0 !important;
    }

    svg.logo path {
      fill: darken(@accent, 2%) !important;

      &:last-child {
        fill: darken(@blue, 8%) !important;
      }
    }

    .v-chip {
      background: @blue;
    }

    .primary--text,
    .name-vtuber {
      color: @accent !important;
    }

    .text-live {
      color: @red;
    }

    .stream-count-chip {
      color: @crust !important;
    }

    .nav-btn.v-btn--active {
      color: @accent !important;
    }

    div.v-sheet.v-alert {
      background: none !important;
      color: @yellow !important;

      .v-icon path {
        fill: @yellow !important;
      }
    }

    hr {
      border-color: @base;
    }

    // Snack
    div.v-snack {
      color: @text;

      div.v-sheet {
        background: @surface0 !important;
      }

      button.v-btn--text {
        color: @text !important;
      }

      button.v-btn--is-elevated.v-btn--has-bg {
        background: @accent !important;
        color: @base;
      }
    }
  }
}

/* ==UserStyle==
@name Zen Browser Docs Catppuccin
@namespace github.com/catppuccin/userstyles/styles/zen-browser-docs
