    .dcg-matrix-expression {
      border-color: @surface0 !important;
    }

    .dcg-keypad-control-btn.dcg-selected::after,
    .dcg-segmented-control-btn.dcg-selected {
      background: @accent !important;
    }

    .dcg-basic-expression.dcg-focused,
    .dcg-matrix-expression.dcg-focused,
    .dcg-latex-expression.dcg-focused {
      border-color: @accent !important;
      box-shadow: inset 0 0 0 1px @accent !important;
    }

    .dcg-resize-action {
      background: @mantle !important;
      border-color: @surface0 !important;
    }

    .dcg-matrix-container, .dcg-segmented-control-btn.dcg-selected {
      border-color: @text !important;
    }

    .dcg-matrix-view .dcg-mq-math-mode.dcg-mq-focused {
      border-bottom-color: @accent !important;
    }

    .dcg-mq-ans {
      border-color: @accent !important;
      color: @accent !important;
      background: fade(@accent, 26%) !important;

      &::after {
        border-color: @accent !important;
        color: @accent !important;
        background: @mantle !important;
      }
    }

    .dcg-keypad-control-btn.dcg-disabled {
      opacity: 1 !important;
      color: @surface1 !important;

      i {
        color: @surface1 !important;
      }
    }

    --dcg-custom-text-color-shaded: @text;

    /* Help Center */
    .lt-container-inner *,
    .lt-topbar,
    .hc-multiselect-toggle li span[aria-label]::before {
      color: @text !important;
    }

    .lt-container-inner a:not(.lt-btn--primary), .lt-topbar__link {
      color: @accent !important;
    }

    .lt-topbar {
      background: @crust !important;
    }

    .lt-topbar__logo {
      filter: @text-filter;
    }

    .lt-hero-unit__bg,
    .lt-footer-submit-ticket,
    .tab,
    .lt-new-request-tip,
    .form-field input,
    .form-field textarea,
    .hc-multiselect-toggle,
    .hc-multiselect-menu {
      background: @mantle !important;
    }

    input[type="submit"], .lt-block-list-item__link, .lt-btn--primary {
      background: @accent !important;
      border-color: @accent !important;
      color: @base !important;
    }

    input[type="search"] {
      background: @crust !important;
      border-color: @text !important;
    }

    .search::before {
      @svg: escape(
        '<svg aria-hidden="true" focusable="false" data-prefix="far" data-icon="search" role="img" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="svg-inline--fa fa-search fa-w-16 fa-3x"><path fill="@{text}" d="M508.5 468.9 387.1 347.5c-2.3-2.3-5.3-3.5-8.5-3.5h-13.2c31.5-36.5 50.6-84 50.6-136C416 93.1 322.9 0 208 0S0 93.1 0 208s93.1 208 208 208c52 0 99.5-19.1 136-50.6v13.2c0 3.2 1.3 6.2 3.5 8.5l121.4 121.4c4.7 4.7 12.3 4.7 17 0l22.6-22.6c4.7-4.7 4.7-12.3 0-17M208 368c-88.4 0-160-71.6-160-160S119.6 48 208 48s160 71.6 160 160-71.6 160-160 160" class=""/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}");
    }

    .lt-block-list-item__link * {
      color: @base !important;
    }

    .lt-custom-block__icon {
      filter: @accent-filter;
    }

    .lt-footer,
    .lt-search-box:not(.lt-search-box--hero-unit),
    .lt-breadcrumbs-wrapper,
    .hc-multiselect-menu li:focus,
    .hc-multiselect-toggle li {
      background: @base !important;
    }

    .lt-scroll-to-top {
      color: @accent !important;
    }

    .pagination-list *, .lt-scroll-to-top, .lt-new-request-tip {
      border-color: @accent !important;
    }

    .lt-header, .lt-search-result {
      border-bottom-color: @surface0 !important;
    }

    .lt-search-result__text em {
      background: @yellow !important;
      color: @base !important;
    }

    .lt-toc--link.is-active > span {
      color: @base !important;
    }

    .tab, .key-command, .hc-multiselect-toggle, .hc-multiselect-menu {
      border-color: @surface0 !important;
    }

    @layer {
      .tabs-link {
        color: @text !important;

        &:hover {
          color: @accent !important;
        }

        &.is-active {
          color: @base !important;
          background: @accent !important;
          border-color: @accent !important;
        }
      }
    }

    .upload-dropzone[data-hc-focus="true"] {
      border-color: @accent !important;
    }

    --input-border-color: @surface0;
    --input-focus-border-color: @accent;

    /* Blog */
    .content-wrap *:not(a), .tag-links > a {
      color: @text !important;
    }

    .article header {
      border-top-color: @surface0 !important;
    }

    *:not(.tag-links) > a:not(.img-card, .btn-blue, .btn-blue-outline) {
      color: @accent;
    }

    .tag-container a {
      border-color: @text !important;

      &:active {
        background: fade(@text, 50%) !important;
      }
    }

    .img-card {
      border-color: @surface2 !important;

      &:hover {
        box-shadow: 0 0 0 1px @surface2 !important;
      }
    }

    .btn-blue {
      background: @accent !important;
      color: @base !important;
    }

    .btn-blue-outline {
      border-color: @accent !important;
      color: @accent !important;

      &:hover {
        box-shadow: 0 0 0 1px @accent !important;
      }
    }

    .dcg-frontpage-landing__announcement {
      background: @accent;
      color: @text;
    }

    .dcg-frontpage-landing__announcement-interior {
      background-color: fade(@crust, 50%);
    }

    /* Exams & Testing Pages (desmos.com/testing/default/{fourfunction,graphing,scientific}) */
    .spa-sample-calculator-view {
      .dcg-sample-calculator__header i.dcg-icon-desmos {
        color: @base !important;
      }

      .dcg-sample-calculator__header {
        background-color: @accent !important;
        color: @base !important;
      }

      .dcg-sample-calculator__calculator-name,
      .dcg-sample-calculator__state-name {
        border-color: @base;
      }
    }

    /* Login/sign up modal */
    .dcg-shared-modal-dialog {
      color: @text;
      --dcg-modal-background-color: @base;

      /* Account signup welcome */
      .dcg-authentication-modal__sublabel {
        color: @subtext0;
      }
      .dcg-authentication-modal__tag {
        background-color: fade(@accent, 20%);

        &:hover {
          background-color: fade(@accent, 30%);
        }

        &.dcg-authentication-modal__tag--selected {
          border-color: @accent;
        }
      }
    }

    /* Account button/dropdown (displays username) */
    .dcg-header-bar__account-menu {
      &.dcg-hovered, &[aria-expanded="true"] {
        background-color: @surface0;
      }
    }
    /* Account settings modal */
    .dcg-shared-account-dialog {
      color: @text;
    }

    /* Desmos Professional (desmos.com/professional) */
    .dcg-professional-hero {
      background-color: @crust;
      color: @text;
    }
    .dcg-section__beta-button {
      color: @base;
      background-color: @text;

      &.dcg-hovered {
        background-color: @subtext1;
      }

      &.dcg-depressed {
        background-color: @subtext0;
      }
    }

    /* "powered by" text above logo */
    .dcg-powered-by {
      color: @text !important;
    }

    /* saved graph titles */
    .dcg-checkbox__content {
      color: @accent;
    }
    /* saved folders */
    .dcg-saved-graphs {
      --dcg-folder-background-color: @mantle;
    }

    /* slider bounds */
    .dcg-slider {
      --dcg-custom-secondary-text-color: @accent;
    }

    /* tutorial (internally called tour/trip) */
    .dcg-trip-interior, .dcg-trip-content {
      background: @base !important;
      color: @text;
    }

    /* folders */
    .dcg-folder {
      --dcg-folder-background-color: @mantle !important;
    }
    .dcg-folder-item-count {
      color: @subtext1;
    }
    .dcg-my-graphs-modal__back-btn-text,
    .dcg-folder__name,
    .dcg-my-graphs-modal__folder-header
      > .dcg-my-graphs-modal-saved-graphs-header,
    .dcg-example-gallery__heading,
    .dcg-saved-graphs-tile__title {
      color: @accent;
    }

    /* folders search (no items found) */
    .dcg-my-graphs-modal-empty-state__heading {
      color: @accent !important;
    }
    .dcg-my-graphs-modal-empty-state__no-search-results {
      color: @subtext1;
    }

    /* new graph button */
    .dcg-new-my-graphs-item__button {
      color: @text !important;
    }
    .dropdown-option-container > .dcg-dropdown-choice[role="menuitem"] {
      color: @text;
    }

    /* update to new behavior button (write f()=random() then enter/exit text mode) */
    .dcg-update-behavior-btn {
      border-color: @surface0 !important;
    }

    /* desmodder: intellisense current variable highlight */
    .pfc-param-selected {
      background: @surface0 !important;
      color: @text !important;
    }

    /* line numbers */
    .dcg-num {
      color: @text;
    }

    /* Banner (e.g. "Saving, sharing, and signing in will be temporarily disabled...") */
    .dcg-header-container .dcg-top-banner {
      color: @text;
      background-color: @base;
    }
  }
}

/* ==UserStyle==
@name docs.deno.com Catppuccin
@namespace github.com/catppuccin/userstyles/styles/docs.deno.com
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/docs.deno.com
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/docs.deno.com/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Adocs.deno.com
@description Soothing pastel theme for docs.deno.com
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("docs.deno.com") {
  @import url("https://prismjs.catppuccin.com/variables.important.css");

  :root.dark {
    #catppuccin(@lightFlavor);
  }
  :root.light {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    --primary: #hsla(@accent)[];
    --background-primary: #hsla(@base)[];
    --background-secondary: #hsla(@mantle)[];
    --background-tertiary: #hsla(@crust)[];
    --foreground-primary: #hsla(@text)[];
    --foreground-secondary: #hsla(@subtext1)[];
    --foreground-tertiary: #hsla(@overlay0)[];
    --foreground-quaternary: #hsla(@surface0)[];
    --runtime-background: 124deg, 100%, 3%;
    --runtime-foreground: 184deg, 100%, 90%;
    --note: #hsla(@blue)[];
    --info: #hsla(@teal)[];
    --caution: #hsla(@yellow)[];
    --tip: #hsla(@green)[];

    .banner-runtime {
      background-color: fade(@accent, 10%);
      color: @text;
      border-color: @accent;
    }
    .banner-deploy {
      background-color: fade(@sky, 10%);
      color: @text;
      border-color: @sky;
    }

    .runtime-link {
      color: @accent;
      text-decoration-color: @accent;

      &:hover {
        color: darken(@accent, 5%);
        text-decoration-color: darken(@accent, 5%);
      }
    }
    .deploy-link {
      color: @sky;
      text-decoration-color: @sky;

      &:hover {
        color: @sapphire;
        text-decoration-color: @sapphire;
      }
    }
    .help-link {
      color: @mauve;
      text-decoration-color: @mauve;

      &:hover {
        color: darken(@mauve, 5%);
        text-decoration-color: darken(@mauve, 5%);
      }
    }

    .heading-runtime {
      text-decoration-color: @accent;
    }
    .heading-deploy {
      text-decoration-color: @sky;
    }
    .heading-purple {
      text-decoration-color: @mauve;
    }

    .runtime-cta {
      background-color: @accent;
      border-color: @accent;

      &:hover {
        background-color: darken(@accent, 5%);
      }
    }
    .jsr-cta {
      background-color: @yellow;
      border-color: @yellow;
      color: @crust;

      &:hover {
        background-color: darken(@yellow, 5%);
      }
    }
    .deploy-cta {
      background-color: @sky;
      border-color: @sky;
      color: @crust;

      &:hover {
        background-color: @sapphire;
      }
    }

    &,
    [data-color-mode] {
      --color-fg-default: @text;
      --color-fg-muted: @subtext1;
      --color-canvas-default: @base;
      --color-canvas-subtle: @mantle;
      --color-border-default: @surface2;
      --color-border-muted: @surface0;
      --color-accent-fg: @accent;
      --color-accent-emphasis: darken(@accent, 5%);
      --color-danger-fg: @red;

      --color-prettylights-syntax-markup-deleted-bg: fade(@red, 20%);
      --color-prettylights-syntax-markup-inserted-bg: fade(@green, 20%);
    }

    // Logo
    .fill-black {
      fill: @text;
    }

    &.light {
      .theme-toggle {
        @svg: escape(
          '<svg viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg" fill="@{text}"><path d="M17.293 13.293A8 8 0 0 1 6.707 2.707a8.001 8.001 0 1 0 10.586 10.586"/></svg>'
        );
        background-image: url("data:image/svg+xml,@{svg}");
      }
    }
    &.dark {
      .theme-toggle {
        @svg: escape(
          '<svg viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg"><path fill="@{text}" d="M10 2a1 1 0 0 1 1 1v1a1 1 0 1 1-2 0V3a1 1 0 0 1 1-1m4 8a4 4 0 1 1-8 0 4 4 0 0 1 8 0m-.464 4.95.707.707a1 1 0 0 0 1.414-1.414l-.707-.707a1 1 0 0 0-1.414 1.414m2.12-10.607a1 1 0 0 1 0 1.414l-.706.707a1 1 0 1 1-1.414-1.414l.707-.707a1 1 0 0 1 1.414 0zM17 11a1 1 0 1 0 0-2h-1a1 1 0 1 0 0 2zm-7 4a1 1 0 0 1 1 1v1a1 1 0 1 1-2 0v-1a1 1 0 0 1 1-1M5.05 6.464A1 1 0 1 0 6.465 5.05l-.708-.707a1 1 0 0 0-1.414 1.414zm1.414 8.486-.707.707a1 1 0 0 1-1.414-1.414l.707-.707a1 1 0 0 1 1.414 1.414M4 11a1 1 0 1 0 0-2H3a1 1 0 0 0 0 2z"/></svg>'
        );
        background-image: url("data:image/svg+xml,@{svg}");
      }
    }

    .markdownBlockTitle {
      background-color: @surface0;
      border-color: @overlay0;
      color: @subtext1;
    }
    .check-icon [stroke="green"] {
      stroke: @green !important;
    }
    .markdown-body .admonition {
      &.note {
        background-color: fade(@blue, 5%);
        .title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="@{blue}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4"/></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}");
        }
      }
      &.tip {
        background-color: fade(@green, 5%);
        .title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="@{green}" stroke-width="1.5"><path stroke-linecap="round" stroke-linejoin="round" d="M12 18v-5.25m0 0a6 6 0 0 0 1.5-.189m-1.5.189a6 6 0 0 1-1.5-.189m3.75 7.478a12.1 12.1 0 0 1-4.5 0m3.75 2.383a14.4 14.4 0 0 1-3 0M14.25 18v-.192c0-.983.658-1.823 1.508-2.316a7.5 7.5 0 1 0-7.517 0c.85.493 1.509 1.333 1.509 2.316V18"/></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}");
        }
      }
      &.caution {
        background-color: fade(@yellow, 5%);

        .title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="@{yellow}"><path fill-rule="evenodd" d="M9.401 3.003c1.155-2 4.043-2 5.197 0l7.355 12.748c1.154 2-.29 4.5-2.599 4.5H4.645c-2.309 0-3.752-2.5-2.598-4.5zM12 8.25a.75.75 0 0 1 .75.75v3.75a.75.75 0 0 1-1.5 0V9a.75.75 0 0 1 .75-.75m0 8.25a.75.75 0 1 0 0-1.5.75.75 0 0 0 0 1.5" clip-rule="evenodd"/></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}");
        }
      }
      &.info {
        background-color: fade(@teal, 5%);

        .title::before {
          @svg: escape(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="@{teal}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4"/></svg>'
          );
          background-image: url("data:image/svg+xml,@{svg}");
        }
      }
    }

    // "Did you find what you needed?"
    .bg-blue-50 {
      background-color: fade(@blue, 20%);
    }
    .border-blue-100 {
      border-color: fade(@blue, 30%);
    }

    // Breadcrumbs
    .crumb-link::after {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" transform="rotate(90)"><path fill="@{overlay1}" d="M7.41 15.41 12 10.83l4.59 4.58L18 14l-6-6-6 6z"/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}");
    }

    // Toggle switches (tutorial filters)
    .slider {
      background-color: @overlay2;
    }
    .filter:checked + .slider {
      background-color: @accent;
    }
    .slider::before {
      background-color: @surface0;
    }

    // Download and install tabbed component
    .deno-tabs > div.deno-tabs-content > div,
    .deno-tabs > ul.deno-tabs-buttons > li > button[data-active="true"] {
      background-color: @surface1;
      color: @text;
      border-color: @overlay0;
    }
    .deno-tabs > ul.deno-tabs-buttons > li > button {
      background-color: @surface0;
      color: @subtext0;
    }
    .markdown-body .deno-tabs pre {
      background-color: @mantle;
      border-color: @overlay0;
    }

    /* API reference */
    .ddoc {
      #ddoc(@token, @color) {
        .text-@{token} {
          color: @color;
        }
        .bg-@{token}\/15 {
          background-color: fade(@color, 15%);
        }
      }

      #ddoc(
        Namespace,
        @yellow,
      );
      #ddoc(
        Interface,
        @sapphire,
      );
      #ddoc(
        Enum,
        @teal,
      );
      #ddoc(
        Class,
        @mauve,
      );
      #ddoc(
        Function,
        @blue,
      );
      #ddoc(
        Variable,
        @lavender,
      );
      #ddoc(
        TypeAlias,
        @pink,
      );
    }
  }
}

#hsla(@color) {
  @raw: e(
    %("%s, %s%, %s%", hue(@color), saturation(@color), lightness(@color))
  );
}

/* ==UserStyle==
@name Lobsters Catppuccin
@namespace github.com/catppuccin/userstyles/styles/lobste.rs
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/lobste.rs
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/lobste.rs/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Alobste.rs
@description Soothing pastel theme for Lobsters
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("lobste.rs") {
  html:has(head > link[rel="stylesheet"][href^="/assets/system-"]) {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  html:has(head > link[rel="stylesheet"][href^="/assets/light-"]) {
    #catppuccin(@lightFlavor);
  }

  html:has(head > link[rel="stylesheet"][href^="/assets/dark-"]) {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --color-bg: @base;

    --color-fg: @text;
    --color-fg-shape: @surface2;

    --color-tag-bg: fade(@yellow, 20%);
    --color-tag-border: fade(@yellow, 20%);

    --color-lobsters-tag-special-bg: fade(@red, 30%);
    --color-lobsters-tag-special-border: fade(@red, 30%);

    --color-tag-media-bg: fade(@blue, 20%);
    --color-tag-media-border: fade(@blue, 30%);

    --color-tag-meta-bg: @surface0;
    --color-tag-meta-border: @surface2;

