@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("tldraw.com") {
  .tl-theme__dark {
    #catppuccin(@darkFlavor);
  }

  .tl-theme__light {
    #catppuccin(@lightFlavor);
  }

  :root:has(.tl-container.tl-theme__dark) .cl-modalContent {
    #catppuccin(@darkFlavor);
  }

  :root:has(.tl-container.tl-theme__light) .cl-modalContent {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --tl-color-background: @mantle;
    --tl-color-low: @base;
    --tl-color-low-border: @base;
    --tl-color-panel: @surface0;
    --tl-color-panel-contrast: @surface1;
    --tl-color-primary: @accent;
    --tl-color-success: @green;
    --tl-color-info: @sky;
    --tl-color-warning: @peach;
    --tl-color-danger: @maroon;
    --tl-color-laser: @red;
    --tl-color-selected: @accent;
    --tl-color-text: @text;
    --tl-color-text-1: @text;
    --tl-color-text-2: @subtext1;
    --tl-color-text-3: @subtext0;
    --tl-color-selected-contrast: @crust;
    --tl-color-snap: @red;
    --tl-color-selection-stroke: @accent;
    --tl-color-divider: @surface1;
    --tl-color-grid: @overlay1;
    --tla-color-primary: @accent;
    --tla-color-primary-hover: fade(@accent, 80%);
    --tla-color-sidebar: @surface0;
    --tla-color-cta: @accent;
    --tla-color-cta-hover: fade(@accent, 80%);
    --tla-color-text-1: @text;
    --tla-color-text-2: @subtext1;
    --tla-color-text-3: @subtext0;
    --tla-color-contrast: @crust;

    @violet: darken(@mauve, 20%);
    @dark-green: darken(@green, 15%);
    @dark-red: darken(@red, 10%);

    button.tla-primary-button > span.i18n-msg {
      color: var(--tla-color-contrast);
    }

    /* colours on canvas */
    div.tl-shape {
      svg.tl-svg-container {
        /* pencil draw shape fills */
        path[fill="#f2f2f2"],
        path[fill="#1d1d1d"] {
          fill: @text;
        }

        path[fill="#9398b0"],
        path[fill="#9fa8b2"] {
          fill: @overlay2;
        }

        path[fill="#e599f7"],
        path[fill="#e085f4"] {
          fill: @mauve;
        }

        path[fill="#ae3ec9"] {
          fill: @violet;
        }

        path[fill="#4f72fc"],
        path[fill="#4465e9"] {
          fill: @blue;
        }

        path[fill="#4dabf7"],
        path[fill="#4ba1f1"] {
          fill: @sky;
        }

        path[fill="#ffc034"],
        path[fill="#f1ac4b"] {
          fill: @yellow;
        }

        path[fill="#f76707"],
        path[fill="#e16919"] {
          fill: @peach;
        }

        path[fill="#099268"] {
          fill: @dark-green;
        }

        path[fill="#40c057"],
        path[fill="#4cb05e"] {
          fill: @green;
        }

        path[fill="#ff8787"],
        path[fill="#f87777"] {
          fill: @red;
        }

        path[fill="#e03131"] {
          fill: @dark-red;
        }

        /* shape outlines (path), arrow strokes (g) */
        path[stroke="#f2f2f2"],
        path[stroke="#1d1d1d"],
        g[stroke="#f2f2f2"],
        g[stroke="#1d1d1d"] {
          stroke: @text;
        }

        path[stroke="#9398b0"],
        path[stroke="#9fa8b2"],
        g[stroke="#9398b0"],
        g[stroke="#9fa8b2"] {
          stroke: @overlay2;
        }

        path[stroke="#e599f7"],
        path[stroke="#e085f4"],
        g[stroke="#e599f7"],
        g[stroke="#e085f4"] {
          stroke: @mauve;
        }

        path[stroke="#ae3ec9"],
        g[stroke="#ae3ec9"] {
          stroke: @violet;
        }

        path[stroke="#4f72fc"],
        path[stroke="#4465e9"],
        g[stroke="#4f72fc"],
        g[stroke="#4465e9"] {
          stroke: @blue;
        }

        path[stroke="#4dabf7"],
        path[stroke="#4ba1f1"],
        g[stroke="#4dabf7"],
        g[stroke="#4ba1f1"] {
          stroke: @sky;
        }

        path[stroke="#ffc034"],
        path[stroke="#f1ac4b"],
        g[stroke="#ffc034"],
        g[stroke="#f1ac4b"] {
          stroke: @yellow;
        }

        path[stroke="#f76707"],
        path[stroke="#e16919"],
        g[stroke="#f76707"],
        g[stroke="#e16919"] {
          stroke: @peach;
        }

        path[stroke="#099268"],
        g[stroke="#099268"] {
          stroke: @dark-green;
        }

        path[stroke="#40c057"],
        path[stroke="#4cb05e"],
        g[stroke="#40c057"],
        g[stroke="#4cb05e"] {
          stroke: @green;
        }

        path[stroke="#ff8787"],
        path[stroke="#f87777"],
        g[stroke="#ff8787"],
        g[stroke="#f87777"] {
          stroke: @red;
        }

        path[stroke="#e03131"],
        g[stroke="#e03131"] {
          stroke: @dark-red;
        }

        /* shape fill - solid */
        path[fill="#2c3036"],
        path[fill="#e8e8e8"] {
          fill: fade(@text, 20%);
        }

        path[fill="#33373c"],
        path[fill="#eceef0"] {
          fill: fade(@overlay2, 20%);
        }

        path[fill="#383442"],
        path[fill="#f5eafa"] {
          fill: fade(@mauve, 20%);
        }

        path[fill="#342938"],
        path[fill="#ecdcf2"] {
          fill: fade(@violet, 20%);
        }

        path[fill="#262d40"],
        path[fill="#dce1f8"] {
          fill: fade(@blue, 20%);
        }

        path[fill="#2a3642"],
        path[fill="#ddedfa"] {
          fill: fade(@sky, 20%);
        }

        path[fill="#3b352b"],
        path[fill="#f9f0e6"] {
          fill: fade(@yellow, 20%);
        }

        path[fill="#3b2e27"],
        path[fill="#f8e2d4"] {
          fill: fade(@peach, 20%);
        }

        path[fill="#253231"],
        path[fill="#d3e9e3"] {
          fill: fade(@dark-green, 20%);
        }

        path[fill="#2a3830"],
        path[fill="#dbf0e0"] {
          fill: fade(@green, 20%);
        }

        path[fill="#3c2b2b"],
        path[fill="#f4dadb"] {
          fill: fade(@red, 20%);
        }

        path[fill="#382726"] {
          fill: fade(@dark-red, 20%);
        }
      }

      /* sticky notes */
      div.tl-note__container {
        &[style*="background-color: rgb(44, 44, 44);"] {
          background-color: @surface0 !important;
        }

        &[style*="background-color: rgb(86, 89, 95);"],
        &[style*="background-color: rgb(192, 202, 211)"] {
          background-color: @overlay2 !important;
