    // On mobile DuckDuckGo paints the header logo on `.header__logo-icon` (which
    // already carries `background-repeat: no-repeat`) and blanks the parent
    // `.header__logo` with `background: none`. Re-blank the parent here so our
    // themed image only lives on the icon and inherits DDG's `no-repeat`,
    // instead of overriding that reset and tiling across the wider parent (#2257).
    &.is-mobile {
      .header__logo,
      .js-logo-ddg {
        background-image: none !important;
      }
    }

